var a=`1055-laksa-penang`;var n=`world-1055`;var s=`MY`;var t=`southeast-asia`;var r=4;var l=60;var o={en:`Laksa Penang`,ua:`Лакса пенанг`};var m={en:`Laksa Penang is a dish from Malaysia prepared with mackerel, lemongrass, galangal, tamarind pulp. This is a home-scale version with measured ingredients in the individual steps where they are used. Mackerel and available rice noodles replace some traditional Penang asam laksa variants.`,ua:`Лакса пенанг, страва кухні країни Малайзія, яку готують із таких продуктів: скумбрія, лемонграс, галангал, м'якоть тамаринду. Кількості в домашньому рецепті прив’язані до окремих етапів приготування. Скумбрія та доступна рисова локшина замінюють окремі традиційні компоненти асам-лакси з Пенанга.`};var g=[{en:`Combine these ingredients in a pot, bring just to a boil and skim any foam. Simmer gently for about 40 minutes to make a flavorful base.`,ua:`З’єднайте складники в каструлі, доведіть майже до кипіння та зніміть піну. Варіть на малому вогні приблизно 40 хвилин для насиченої основи.`,t:[`simmering`,`skimming-foam`],m:40,i:[[`fish-stock`,1100,`ml`],[`mackerel`,500,`g`],[`lemongrass`,2,`pcs`],[`galangal`,30,`g`]]},{en:`Combine the listed ingredients in a bowl until evenly mixed; avoid overworking delicate components.`,ua:`З’єднайте зазначені складники в мисці до однорідності; не перемішуйте ніжні компоненти надто довго.`,t:[`mixing`],m:7,i:[[`tamarind-pulp`,75,`g`],[`shrimp-paste`,20,`g`],[`bird-s-eye-chili`,3,`pcs`]]},{en:`Cook the listed ingredients in simmering water for about 8 minutes until tender; drain well if necessary.`,ua:`Варіть зазначені складники у воді приблизно 8 хвилин до м’якості; за потреби добре злийте воду.`,t:[`boiling`],m:8,i:[[`rice-noodles`,450,`g`],[`water`,1100,`ml`]]},{en:`Assemble the cooled components with the listed fillings or toppings. Refrigerate briefly if needed to set the layers.`,ua:`Зберіть охолоджені частини з зазначеними начинками або покриттям. За потреби ненадовго охолодіть для стабілізації шарів.`,t:[`layered-assembly`,`garnishing`],m:5,i:[[`papaya`,170,`g`],[`cucumber`,150,`g`],[`mint`,25,`g`],[`red-onion`,110,`g`]]}];var d={slug:a,id:n,country:`MY`,region:t,servings:4,minutes:60,title:o,text:m,steps:g};export{s as country,d as default,n as id,l as minutes,t as region,r as servings,a as slug,g as steps,m as text,o as title};